  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	
  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	
 14	    private final Rooms rooms;
 15	    private final ReservationStore store;
 16	    private final PriceCalculator priceCalculator;
 17	    private final EmailSender emailSender;
 18	    private final ReservationNotifier notifier;
 19	
 20	    public ReservationService(
 21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender,
 22	            ReservationNotifier notifier) {
 23	        this.rooms = rooms;
 24	        this.store = store;
 25	        this.priceCalculator = priceCalculator;
 26	        this.emailSender = emailSender;
 27	        this.notifier = notifier;
 28	    }
 29	
 30	    public synchronized Reservation create(NewReservation request) {
 31	        if (!request.checkOut().isAfter(request.checkIn())) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 33	        }
 34	        if (request.guests() < 1) {
 35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 36	        }
 37	        Room room = rooms.find(request.roomNumber())
 38	                .orElseThrow(() -> new HotelException(
 39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 40	        if (request.guests() > room.capacity()) {
 41	            throw new HotelException(
 42	                    ErrorCode.CAPACITY_EXCEEDED,
 43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 44	        }
 45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 46	            throw new HotelException(
 47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 48	        }
 49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 50	        return store.add(request, price);
 51	    }
 52	
 53	    public Reservation find(long reservationId) {
 54	        return store.find(reservationId)
 55	                .orElseThrow(() -> new HotelException(
 56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 57	    }
 58	
 59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 60	    public synchronized Reservation confirm(long reservationId) {
 61	        Reservation reservation = find(reservationId);
 62	        if (reservation.status() != ReservationStatus.PENDING) {
 63	            throw notAllowed(reservation, "confirm");
 64	        }
 65	        reservation.confirmPayment();
 66	        store.update(reservation);
 67	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 68	        emailSender.send(
 69	                reservation.guest().email(),
 70	                "Reserva confirmada - " + HOTEL_NAME,
 71	                confirmationEmailBody(reservation, receipt));
 72	        notifier.notifyConfirmed(reservation, reservation.roomNumber());
 73	        return reservation;
 74	    }
 75	
 76	    /**
 77	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 78	     * reservation was never paid, so nothing comes back).
 79	     */
 80	    public synchronized Reservation cancel(long reservationId) {
 81	        Reservation reservation = find(reservationId);
 82	        if (reservation.status() != ReservationStatus.PENDING
 83	                && reservation.status() != ReservationStatus.CONFIRMED) {
 84	            throw notAllowed(reservation, "cancel");
 85	        }
 86	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
 87	        BigDecimal refund = switch (reservation.ratePlan()) {
 88	            case STANDARD -> reservation.amountPaid();
 89	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 90	        };
 91	        reservation.cancel(refund);
 92	        store.update(reservation);
 93	        notifier.notifyCancelled(reservation, reservation.roomNumber(), wasConfirmed);
 94	        return reservation;
 95	    }
 96	
 97	    public synchronized Reservation checkIn(long reservationId) {
 98	        Reservation reservation = find(reservationId);
 99	        if (reservation.status() != ReservationStatus.CONFIRMED) {
100	            throw notAllowed(reservation, "check in");
101	        }
102	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
103	        store.update(reservation);
104	        return reservation;
105	    }
106	
107	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
108	    public synchronized ReservationReceipt checkOut(long reservationId) {
109	        Reservation reservation = find(reservationId);
110	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
111	            throw notAllowed(reservation, "check out");
112	        }
113	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
114	        store.update(reservation);
115	        return new ReservationReceipt(reservation, roomOf(reservation));
116	    }
117	
118	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
119	    public ReservationReceipt receiptCopy(long reservationId) {
120	        Reservation reservation = find(reservationId);
121	        if (!reservation.isPaid()) {
122	            throw notAllowed(reservation, "issue a receipt for");
123	        }
124	        return new ReservationReceipt(reservation, roomOf(reservation));
125	    }
126	
127	    private Room roomOf(Reservation reservation) {
128	        return rooms.find(reservation.roomNumber()).orElseThrow();
129	    }
130	
131	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
132	        return "Olá, " + reservation.guest().name() + "!\n\n"
133	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
134	                + receipt.text() + "\n"
135	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
136	                + "Até breve!\n";
137	    }
138	
139	    private static HotelException notAllowed(Reservation reservation, String operation) {
140	        return new HotelException(
141	                ErrorCode.OPERATION_NOT_ALLOWED,
142	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
143	    }
144	}
